import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow_for_ask_for_approval_action'],
        name: 'Test flow for ask for approval action fluent',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_flow_for_ask_for_approval_action_trigger'] },

        {
            table: 'incident',
        }
    ),
    (_params) => {
        const askForApprovalAction = wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['test_flow_for_ask_for_approval_action_step1'],
                annotation: 'Ask for approval',
            },
            {
                record: wfa.dataPill(_params.trigger.current, 'reference'),
                table: 'incident',
                approval_reason: 'Test approval reason',
                approval_field: 'approval',
                journal_field: 'approval_history',
                due_date: '',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: ['62826bf03710200044e0bfc8bcbe5df1'],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'All',
                                        users: ['a8f98bb0eb32010045e1a5115206fe3a'],
                                        groups: ['f6498860436012103cf32f0b76b8f2ce'],
                                        manual: false,
                                    },
                                    {
                                        ruleType: 'Res',
                                        users: ['0a826bf03710200044e0bfc8bcbe5d7a'],
                                        groups: ['019ad92ec7230010393d265c95c260dd'],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'Count',
                                        count: 3,
                                        users: ['71826bf03710200044e0bfc8bcbe5d3b'],
                                        groups: [],
                                        manual: false,
                                    },
                                    {
                                        ruleType: 'Percent',
                                        percent: 40,
                                        users: [],
                                        groups: ['477a05d153013010b846ddeeff7b1225'],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                        {
                            action: 'Rejects',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: ['62826bf03710200044e0bfc8bcbe5df1'],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'Any',
                                        users: ['a8f98bb0eb32010045e1a5115206fe3a'],
                                        groups: ['f6498860436012103cf32f0b76b8f2ce'],
                                        manual: false,
                                    },
                                    {
                                        ruleType: 'Any',
                                        users: ['0a826bf03710200044e0bfc8bcbe5d7a'],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(askForApprovalAction.approval_state, 'choice')}=approved`,
                annotation: 'If Approved',
                $id: Now.ID['test_flow_for_ask_for_approval_action_step2'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['test_flow_for_ask_for_approval_action_step3'],
                    },
                    {
                        log_level: 'info',
                        log_message: 'user approved it',
                    }
                )
            }
        )
    }
)
